# configuration file /etc/nginx/nginx.conf:
user www-data;
worker_processes auto;

events { worker_connections 1024; }

http {
    include mime.types;
    client_max_body_size 20m;
    ssl_protocols TLSv1.2 TLSv1.3;

    server {
        listen 443 ssl;
        server_name api.pantry.dev;
        ssl_certificate     /etc/letsencrypt/live/api.pantry.dev/fullchain.pem;
        ssl_certificate_key /etc/letsencrypt/live/api.pantry.dev/privkey.pem;
        location / { proxy_pass http://127.0.0.1:8080; }
    }

    server {
        listen 443 ssl;
        server_name www.pantry.dev pantry.dev;
        ssl_certificate     /etc/letsencrypt/live/pantry.dev/fullchain.pem;
        ssl_certificate_key /etc/letsencrypt/live/pantry.dev/privkey.pem;
        root /var/www/pantry;
    }

    server {
        listen 443 ssl;
        server_name admin.pantry.dev;
        ssl_certificate     /etc/letsencrypt/live/admin.pantry.dev/fullchain.pem;
        ssl_certificate_key /etc/letsencrypt/live/admin.pantry.dev/privkey.pem;
        location / { proxy_pass http://127.0.0.1:8081; }
    }

    server {
        listen 80 default_server;
        return 301 https://$host$request_uri;
    }
}
